class TestAsyncBehavior:
    """Tests for async behavior and concurrency."""

    def test_concurrent_health_checks(self):
        """Multiple concurrent health checks must all succeed."""
        async def run_concurrent_checks():
            async def check():
                with client() as test_client:
                    return test_client.get("/health")
            
            tasks = [check() for _ in range(10)]
            results = await asyncio.gather(*tasks)
            return results

        results = asyncio.run(run_concurrent_checks())
        for response in results:
            assert response.status_code == 200
            data = response.json()
            assert data["status"] == "healthy"

    def test_async_service_methods(self):
        """Service methods must support async invocation."""
        with patch("tests.test_main.get_health_service") as mock_get:
            mock_service = MagicMock()
            mock_service.check_health = AsyncMock(return_value={
                "status": "healthy",
                "timestamp": datetime.now(timezone.utc).isoformat(),
                "version": "1.0.0"
            })
            mock_get.return_value = mock_service
            
            async def test_async_call():
                result = await mock_service.check_health()
                return result
            
            result = asyncio.run(test_async_call())
            assert result["status"] == "healthy"


